<original_code>
#include <bits/stdc++.h>
using namespace std;

#define p_m make_pair
#define iter(x) (x).begin(), (x).end()
#define sz(x) ((int)(x).size())
#define first f
#define second s
typedef long long ll;

mt19937 rng(chrono::steady_clock::now().time_since_epoch().count());
const int N = 12, INF = 1000000009;
const int delta_x[4] = {0, 1, 0, -1};
const int delta_y[4] = {1, 0, -1, 0};

struct Pos {
    int row, col;
    Pos() {}
    Pos(int _row, int _col) : row(_row), col(_col) {}
};

int n, t;
char gridA[N][N], gridB[N][N];

int start_x, start_y;
int dist[N][N];

void do_bfs(int d[N][N], int sx, int sy) {
    bool vis[N][N] = {};
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            d[i][j] = INF;
    queue<Pos> q;
    vis[sx][sy] = true;
    d[sx][sy] = 0;
    q.push(Pos(sx, sy));
    while (!q.empty()) {
        Pos c = q.front(); q.pop();
        for (int dir_idx = 0; dir_idx < 4; ++dir_idx) {
            Pos nxt = c;
            nxt.row += delta_x[dir_idx];
            nxt.col += delta_y[dir_idx];
            if (nxt.row >= 0 && nxt.row < n && nxt.col >= 0 && nxt.col < n
                && !vis[nxt.row][nxt.col]
                && gridA[nxt.row][nxt.col] >= '0'
                && gridA[nxt.row][nxt.col] <= '9') {
                vis[nxt.row][nxt.col] = true;
                d[nxt.row][nxt.col] = d[c.row][c.col] + 1;
                q.push(nxt);
            }
        }
    }
}

bool residual_flow[N * 6][N][N][N][N];
bool can_reach[N][N][N][N];

int g_matrix[2 * N * N][2 * N * N];

int parent_node[2 * N * N];
bool visited_nodes[2 * N * N];

bool bfs_flow() {
    memset(visited_nodes, 0, sizeof(visited_nodes));
    memset(parent_node, 0, sizeof(parent_node));
    queue<int> q;
    visited_nodes[0] = true;
    q.push(0);
    while (!q.empty()) {
        int node = q.front(); q.pop();
        if (node == 2 * n * n + 1)
            return true;
        for (int h = 0; h <= 2 * n * n + 1; ++h) {
            if (g_matrix[node][h]) {
                if (!visited_nodes[h]) {
                    visited_nodes[h] = true;
                    parent_node[h] = node;
                    q.push(h);
                }
            }
        }
    }
    return false;
}

void process() {
    scanf("%d%d", &n, &t);
    for (int i = 0; i < n; ++i)
        scanf(" %s", gridA[i]);
    for (int i = 0; i < n; ++i)
        scanf(" %s", gridB[i]);
    scanf("%d%d", &start_x, &start_y);
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (gridA[i][j] == 'Z') {
                start_x = i; start_y = j;
            }
    do_bfs(dist, start_x, start_y);
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if ('0' <= gridA[i][j] && gridA[i][j] <= '9')
                residual_flow[0][i][j][i][j] = true;
    for (int step = 0; step < t; ++step) {
        for (int sx = 0; sx < n; ++sx)
            for (int sy = 0; sy < n; ++sy)
                for (int x = 0; x < n; ++x)
                    for (int y = 0; y < n; ++y) {
                        if (!residual_flow[step][sx][sy][x][y]) continue;
                        if (dist[x][y] <= step) continue;
                        for (int dir_idx = 0; dir_idx < 4; ++dir_idx) {
                            int hx = x + delta_x[dir_idx];
                            int hy = y + delta_y[dir_idx];
                            if (hx >= 0 && hx < n && hy >= 0 && hy < n && '0' <= gridA[hx][hy] && gridA[hx][hy] <= '9') {
                                if (dist[hx][hy] >= step + 1)
                                    residual_flow[step + 1][sx][sy][hx][hy] = true;
                            }
                        }
                    }
    }
    for (int step = 0; step <= t; ++step)
        for (int sx = 0; sx < n; ++sx)
            for (int sy = 0; sy < n; ++sy)
                for (int x = 0; x < n; ++x)
                    for (int y = 0; y < n; ++y)
                        if (residual_flow[step][sx][sy][x][y])
                            can_reach[sx][sy][x][y] = true;

    for (int x1 = 0; x1 < n; ++x1)
        for (int y1 = 0; y1 < n; ++y1)
            if ('0' <= gridA[x1][y1] && gridA[x1][y1] <= '9')
                g_matrix[0][x1 * n + y1 + 1] = gridA[x1][y1] - '0';

    for (int x2 = 0; x2 < n; ++x2)
        for (int y2 = 0; y2 < n; ++y2)
            if ('0' <= gridB[x2][y2] && gridB[x2][y2] <= '9')
                g_matrix[n * n + x2 * n + y2 + 1][2 * n * n + 1] = gridB[x2][y2] - '0';

    for (int x1 = 0; x1 < n; ++x1)
        for (int y1 = 0; y1 < n; ++y1)
            for (int x2 = 0; x2 < n; ++x2)
                for (int y2 = 0; y2 < n; ++y2) {
                    if (!('0' <= gridA[x1][y1] && gridA[x1][y1] <= '9')) continue;
                    if (!('0' <= gridA[x2][y2] && gridA[x2][y2] <= '9')) continue;
                    if (!can_reach[x1][y1][x2][y2]) continue;
                    g_matrix[x1 * n + y1 + 1][n * n + x2 * n + y2 + 1] = INF;
                }

    while (bfs_flow()) {
        int min_flow_value = INF;
        for (int i = 2 * n * n + 1; i; i = p[i]) {
            min_flow_value = min(min_flow_value, g_matrix[p[i]][i]);
        }
        for (int i = 2 * n * n + 1; i; i = p[i]) {
            g_matrix[p[i]][i] -= min_flow_value;
            g_matrix[i][p[i]] += min_flow_value;
        }
    }

    int answer = 0;
    for (int i = 0; i <= 2 * n * n + 1; ++i)
        answer += g_matrix[i][0];

    printf("%d\n", answer);
}

int main() {
    #ifdef SOMETHING
    freopen("input.txt", "r", stdin);
    #endif
    process();
    return 0;
}
